import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.math.BigInteger;
import java.util.StringTokenizer;

public class Main {
    static final BigInteger MOD = BigInteger.valueOf(998244353L);
    static BigInteger[] fact;
    static BigInteger[] invFact;

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();
        int lim = n + m;

        fact = new BigInteger[lim + 1];
        invFact = new BigInteger[lim + 1];
        fact[0] = BigInteger.ONE;
        for (int i = 1; i <= lim; i++) {
            fact[i] = fact[i - 1].multiply(BigInteger.valueOf(i)).mod(MOD);
        }
        invFact[lim] = fact[lim].modInverse(MOD);
        for (int i = lim; i >= 1; i--) {
            invFact[i - 1] = invFact[i].multiply(BigInteger.valueOf(i)).mod(MOD);
        }

        BigInteger phaseSize = BigInteger.ONE;
        BigInteger p = BigInteger.ONE;
        for (int i = 1; i <= n; i++) {
            p = p.multiply(BigInteger.valueOf(n - i + 1)).mod(MOD);
            p = p.multiply(inv(lim - i + 1)).mod(MOD);
            phaseSize = phaseSize.add(p).mod(MOD);
        }

        BigInteger answer = BigInteger.ZERO;
        for (int k = 1; k <= n; k++) {
            BigInteger numPhases = BigInteger.valueOf((long) m + k).multiply(inv(k)).mod(MOD);
            BigInteger e = numPhases.multiply(phaseSize).mod(MOD);
            BigInteger term = ncr(n, k).multiply(e).mod(MOD);
            if ((k & 1) == 1) {
                answer = answer.add(term).mod(MOD);
            } else {
                answer = answer.subtract(term).mod(MOD);
            }
        }

        System.out.println(answer);
    }

    static BigInteger inv(int x) {
        return fact[x - 1].multiply(invFact[x]).mod(MOD);
    }

    static BigInteger ncr(int n, int r) {
        if (r < 0 || r > n) return BigInteger.ZERO;
        return fact[n].multiply(invFact[r]).mod(MOD).multiply(invFact[n - r]).mod(MOD);
    }

    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
